  ('598785103722294446', 'Being Mary Tyler Moore', 2023, 'Documentary', 'James Adolphus, James Adolphus', null, 'Mary Tyler Moore, Ed Asner, Emanuel Azenberg, James L. Brooks, James Burrows, Debra Martin Chase, Katie Couric, Joan Darling', 'PG', 'With unprecedented access to the Mary Tyler Moore Estate, friends, family, and colleagues, Being Mary Tyler Moore constructs an intimate mosaic of Mary''s sixty-year career in show business.', 'With unprecedented access to the Mary Tyler Moore Estate, friends, family, and colleagues, Being Mary Tyler Moore constructs an intimate mosaic of Mary''s sixty-year career in show business.', 'https://image.tmdb.org/t/p/w500/2A6MSRDblLl7X4gVPVxigc7psqG.jpg', 'tmdb:movie:1072873'),
  ('1087211154411309415', 'Being the Ricardos', 2021, 'Drama, History', 'Jeff Cronenweth, Aaron Sorkin', 'Aaron Sorkin', 'Nicole Kidman, Javier Bardem, J.K. Simmons, Nina Arianda, Tony Hale, Alia Shawkat, Jake Lacy, Linda Lavin', 'R', 'Lucille Ball and Desi Arnaz face a crisis that could end their careers and another that could end their marriage.', 'Lucille Ball and Desi Arnaz face a crisis that could end their careers and another that could end their marriage.', 'https://image.tmdb.org/t/p/w500/oztBLWdRk5gApYmNdADXvXkLT5m.jpg', 'tmdb:movie:517088'),
